def stage_entry_statuses(fsm_spec: FSMSpec, legal_in: tuple[str, ...]) -> set[str]:
    """The statuses in `legal_in` where the work it scopes first becomes available.

    Within-set first: a scoped status qualifies when no OTHER scoped status transitions
    into it, so arriving there from outside the scope still counts as arriving first.
    A cyclic scope leaves that empty (building <-> review), so it falls back to the
    scoped statuses nearest the FSM's initial status - the entry point the page reaches
    soonest. Unreachable statuses are not candidates.
    """
    scoped = set(legal_in)
    incoming: dict[str, set[str]] = {}
    for _event, source, dest, _agency in fsm_spec.transitions:
        incoming.setdefault(dest, set()).add(source)
    unentered = {status for status in scoped if not (incoming.get(status, set()) & scoped)}
    if unentered:
        return unentered
    distance = _distance_from_initial(fsm_spec)
    reachable = {status for status in scoped if status in distance}
    if not reachable:
        return set()
    nearest = min(distance[status] for status in reachable)
    return {status for status in reachable if distance[status] == nearest}


def _distance_from_initial(fsm_spec: FSMSpec) -> dict[str, int]:
    """Edge count from the FSM's initial status to each status it can reach (BFS).

    A status absent from the result is unreachable, which is how the fallback tells
    'not yet arrived at' from 'never arrives at'.
    """
    outgoing: dict[str, set[str]] = {}
    for _event, source, dest, _agency in fsm_spec.transitions:
        outgoing.setdefault(source, set()).add(dest)
    distance = {fsm_spec.initial: 0}
    queue = deque([fsm_spec.initial])
    while queue:
        current = queue.popleft()
        for nxt in outgoing.get(current, ()):
            if nxt not in distance:
                distance[nxt] = distance[current] + 1
                queue.append(nxt)
    return distance

def field_setter_edges(page, page_type, blocked_events=()):
    allowed = fsm.allowed_events(page_type.fsm, page.status)
    stage_events = allowed - set(blocked_events)
    required = {
        section_field
        for command in page_type.commands
        if _is_status_transition(command) and command.event in stage_events
        for section_field in command.requires
    }
    # A wholly parent-gated stage is not this page's work yet, so nothing it scopes is
    # offered - the same reasoning that keeps `required` empty there.
    entry_open = not allowed or bool(stage_events)
    legal = legal_commands(page, page_type)
    setters: dict[tuple[str, str], str] = {}
    for command in page_type.commands:
        section, field = command.section, command.field
        if section is None or field is None:
            continue
        if not legal.get(command.name) or not is_field_setter(command):
            continue
        target = (section, field)
        stage_required = target in required
        stage_entry = (
            entry_open and command.legal_in is not None
            and page.status in stage_entry_statuses(page_type.fsm, command.legal_in)
        )
        if stage_required or stage_entry:
            setters.setdefault(target, command.name)
    return [_field_setter_edge(page, page_type, section, field, command_name)
            for (section, field), command_name in setters.items()]

