# tests/test_cleanup.py - replace the existing _p helper with this one.
def _p(page_id, children=(), archived=False, expires_at=None, delete_scheduled=False) -> Page:
    return Page(id=page_id, type="test-fields", title=page_id, status="active",
                child_ids=list(children), archived=archived, expires_at=expires_at,
                delete_scheduled=delete_scheduled)

# was test_classify_stamps_hidden_and_unfiled_only
def test_classify_stamps_scheduled_and_unfiled_only():
    ws = _ws(_p("root", ["live", "arch"]), _p("live"),
             _p("arch", archived=True, delete_scheduled=True),
             _p("lost"), roots=["root"])
    assert cleanup.classify(ws, NOW).stamp == {"arch": SOON, "lost": SOON}


def test_classify_never_restamps_an_existing_expiry():
    ws = _ws(_p("root", ["arch"]),
             _p("arch", archived=True, delete_scheduled=True, expires_at=PAST), roots=["root"])
    assert cleanup.classify(ws, NOW).stamp == {}


def test_classify_prunes_only_maximal_subtree_roots():
    # Parent and child both expired: only the parent is named.
    ws = _ws(_p("root", ["arch"]),
             _p("arch", ["kid"], archived=True, delete_scheduled=True, expires_at=PAST),
             _p("kid", expires_at=PAST), roots=["root"])
    assert cleanup.classify(ws, NOW).prune == ["arch"]

def test_classify_does_not_stamp_an_archived_page_nobody_scheduled():
    ws = _ws(_p("root", ["arch"]), _p("arch", archived=True), roots=["root"])
    assert cleanup.classify(ws, NOW).stamp == {}


def test_classify_clears_the_stamp_of_an_archived_page_nobody_scheduled():
    # The migration path: a stamp written under the old rule is dropped by the first sweep.
    ws = _ws(_p("root", ["arch"]), _p("arch", archived=True, expires_at=PAST), roots=["root"])
    sweep = cleanup.classify(ws, NOW)
    assert sweep.clear == ["arch"]
    assert sweep.prune == []


def test_classify_does_not_stamp_a_hidden_descendant_of_a_scheduled_page():
    ws = _ws(_p("root", ["arch"]),
             _p("arch", ["kid"], archived=True, delete_scheduled=True), _p("kid"), roots=["root"])
    assert cleanup.classify(ws, NOW).stamp == {"arch": SOON}


def test_classify_ignores_a_scheduled_page_that_is_still_findable():
    # Reachable only by hand-editing the file; a visible page must never be deleted.
    ws = _ws(_p("root", ["odd"]), _p("odd", delete_scheduled=True, expires_at=PAST), roots=["root"])
    sweep = cleanup.classify(ws, NOW)
    assert sweep.stamp == {}
    assert sweep.clear == ["odd"]
    assert sweep.prune == []


def test_classify_still_stamps_an_unfiled_orphan_nobody_scheduled():
    ws = _ws(_p("root"), _p("lost"), roots=["root"])
    assert cleanup.classify(ws, NOW).stamp == {"lost": SOON}

# --- archiving -----------------------------------------------------------
def _set_page_archive_state(
    self, workspace_id: str, page_id: str, *,
    archived: bool | None = None, delete_scheduled: bool | None = None,
) -> Page:
    with self._transaction_lock_for(workspace_id):
        workspace = self.load_workspace(workspace_id)
        page = workspace.get_page(page_id)
        if page is None:
            raise NotFoundError(f"Page '{page_id}' not found in workspace '{workspace_id}'.")
        if self._is_pinned_child(workspace, page):
            raise IllegalCommandError(
                f"Page '{page_id}' is a pinned auto-created child; archive/unarchive its parent instead."
            )

        def apply(target: Page) -> None:
            if archived is not None:
                target.archived = archived
            if delete_scheduled is not None:
                target.delete_scheduled = delete_scheduled

        apply(page)
        # A pinned child's archive state mirrors its parent's: cascade onto this page's pinned children.
        parent_type = get_page_type(page.type)
        for child_id in page.child_ids:
            child = workspace.pages.get(child_id)
            if child is not None and is_auto_child_type(parent_type, child.type):
                apply(child)
        self._touch_and_save(workspace)
        return page

def archive_page(self, workspace_id: str, page_id: str) -> Page:
    return self._set_page_archive_state(workspace_id, page_id, archived=True)

def unarchive_page(self, workspace_id: str, page_id: str) -> Page:
    # Unarchiving is the rescue path, so it also calls off a scheduled deletion.
    return self._set_page_archive_state(workspace_id, page_id, archived=False, delete_scheduled=False)

def schedule_page_deletion(self, workspace_id: str, page_id: str) -> Page:
    # Scheduling implies archiving, so a page queued for deletion is never left in a live view.
    return self._set_page_archive_state(workspace_id, page_id, archived=True, delete_scheduled=True)

def unschedule_page_deletion(self, workspace_id: str, page_id: str) -> Page:
    # The page stays archived; only the deletion is called off.
    return self._set_page_archive_state(workspace_id, page_id, delete_scheduled=False)

