# src/session_activity.py
"""A short-lived, in-memory record of when each MCP session last ran a tool, and the rules for the
optional `sessionId` argument an agent uses to say which session it is working from.

Everything here is a function of its inputs: the time is passed in, and nothing reaches disk, so
losing the record on a restart or reload costs nothing. The server reads the clock and the request.
"""

from __future__ import annotations

from datetime import datetime, timedelta

SESSION_TTL = timedelta(minutes=15)
SESSION_ID_ARGUMENT = "sessionId"


class SessionActivity:
    """When each session last ran a tool, kept for `SESSION_TTL` after that. `record` and `active`
    evict what has expired, so nothing needs a timer and the map holds only recent sessions."""

    def __init__(self) -> None:
        self._last_active: dict[str, datetime] = {}

    def record(self, session_id: str, now: datetime) -> None:
        self._last_active[session_id] = now
        self._evict(now)

    def active(self, now: datetime) -> dict[str, datetime]:
        self._evict(now)
        return dict(self._last_active)

    def _evict(self, now: datetime) -> None:
        self._last_active = {session_id: last_active
                             for session_id, last_active in self._last_active.items()
                             if now - last_active < SESSION_TTL}

