# Markdown emphasis/link tokens rejected inside a plain-text run. Kept deliberately narrow
# (bold/link markers) so ordinary prose containing a lone `*` or `_` or even a file with
# double '__' is not falsely rejected. A backtick is judged by count instead, since balanced
# ones are literal text.
_MARKDOWN_TOKENS = ("**", "](")


# src/pagetypes/core/validation.py
def _reject_markdown(text: str) -> None:
    for token in _MARKDOWN_TOKENS:
        if token in text:
            raise ValidationError(
                f"Markdown syntax ('{token}') is not allowed in a text run - express emphasis " +
                f"or a link with a structured run (e.g. {{'text': '…', 'bold': true}}) instead."
            )
    if text.count("`") % 2:
        raise ValidationError(
            "Unbalanced backticks in a text run - backticks are literal text only in pairs; " +
            "close the pair, or write inline code with a structured run ({'code': '…'})."
        )

