def _size(events: list[dict[str, Any]]) -> int:
    return sum(len(json.dumps(event, ensure_ascii=False)) for event in events)


def append(events: list[dict[str, Any]], event: dict[str, Any], cap: int) -> bool:
    """Append `event`, then trim oldest-first to `cap` and to BYTE_BUDGET.

    Returns True when anything was trimmed. Never raises on a well-formed event.
    """
    events.append(event)
    trimmed = False
    while len(events) > cap:
        events.pop(0)
        trimmed = True
    while len(events) > 1 and _size(events) > BYTE_BUDGET:
        events.pop(0)
        trimmed = True
    return trimmed

