from src.model import Workspace
from src.eventlog import baseline


def _workspace(workspace_id="ws:1", name="demo"):
    return Workspace(id=workspace_id, name=name)


def _add(workspace, page_id, type_tag="test-fields", title="T", status="active",
         parent=None, archived=False):
    page = Page(id=page_id, type=type_tag, title=title, status=status,
                parent_id=parent, archived=archived)
    workspace.pages[page_id] = page
    if parent is None:
        workspace.root_page_ids.append(page_id)
    else:
        workspace.pages[parent].child_ids.append(page_id)
    return page


def test_baseline_lists_pages_depth_first_with_status():
    workspace = _workspace()
    _add(workspace, "test-fields:1", title="Root")
    _add(workspace, "test-fields:2", title="Child", status="draft", parent="test-fields:1")
    assert baseline(workspace, at=AT) == {"at": AT, "pages": [
        {"id": "test-fields:1", "type": "test-fields", "title": "Root", "status": "active"},
        {"id": "test-fields:2", "type": "test-fields", "title": "Child", "status": "draft"},
    ]}


def test_baseline_includes_archived_pages():
    workspace = _workspace()
    _add(workspace, "test-fields:9", title="Gone", archived=True)
    assert [page["id"] for page in baseline(workspace, at=AT)["pages"]] == ["test-fields:9"]


def test_baseline_survives_a_cycle_in_a_corrupt_file():
    workspace = _workspace()
    _add(workspace, "test-fields:1")
    workspace.pages["test-fields:1"].child_ids.append("test-fields:1")
    assert len(baseline(workspace, at=AT)["pages"]) == 1

def baseline(workspace: Workspace, at: str) -> dict[str, Any]:
    """The one-time tracking-began snapshot: {"at": at, "pages": [...]}."""
    pages: list[dict[str, Any]] = []
    seen: set[str] = set()

    def walk(page_id: str) -> None:
        page = workspace.pages.get(page_id)
        if page is None or page_id in seen:
            return
        seen.add(page_id)
        pages.append({"id": page.id, "type": page.type,
                      "title": page.title, "status": page.status})
        for child_id in page.child_ids:
            walk(child_id)

    for root_id in workspace.root_page_ids:
        walk(root_id)
    return {"at": at, "pages": pages}

