@dataclass
class Tx:
    workspace: Workspace
    actor: str          # 'agent' | 'person'
    at: str             # _now(), shared by every event of this transaction


@contextmanager
def _transaction(self, workspace_id: str, *, actor: str = 'agent') -> Iterator[Tx]:
    if actor not in ('agent', 'person'):
        raise ValidationError(f'Unknown actor {actor!r}; expected agent or person.')
    with self._transaction_lock_for(workspace_id):
        workspace = self.load_workspace(workspace_id)   # NotFoundError exactly as today
        tx = Tx(workspace=workspace, actor=actor, at=_now())
        yield tx
        # Only reached when the body raised nothing, so an aborted transaction
        # records nothing and seeds nothing.
        if workspace.tracking_began is None:
            workspace.tracking_began = eventlog.baseline(workspace, at=tx.at)
        self._touch_and_save(workspace)

def _element_status(page: Page, section: str, field: str, element_id: object) -> str | None:
    # The status of one list element, or None when the element is not there.
    for element in page.sections.get(section, {}).get(field, []) or []:
        if isinstance(element, dict) and element.get('id') == element_id:
            status = element.get('status')
            return status if isinstance(status, str) else None
    return None

KEEP = {"src.hmr_server", "src.hmr_live_refresh"}            # own the reloader and the live sockets
KEEP_UNLESS_CHANGED = {"src.event_cache", "src._hmr_debug"}  # import nothing from src; hold state


def reload_all(changed: set[Path]) -> BaseException | None:
    """Re-import every src module from disk; on failure put the last good set back."""
    snapshot = {n: m for n, m in sys.modules.items() if n == "src" or n.startswith("src.")}
    for name, module in snapshot.items():
        if name in KEEP or (name in KEEP_UNLESS_CHANGED and Path(module.__file__) not in changed):
            continue
        del sys.modules[name]
    for path in changed:  # pyc validation is mtime-in-seconds + size
        Path(importlib.util.cache_from_source(str(path))).unlink(missing_ok=True)
    importlib.invalidate_caches()
    try:
        importlib.import_module("src.server")
    except Exception as exc:
        for name in [n for n in sys.modules if n == "src" or n.startswith("src.")]:
            del sys.modules[name]
        sys.modules.update(snapshot)
        return exc
    return None

