type Event = dict[str, Any]

def created(page: Page) -> Event:
    return {"page": page.id, "kind": "created", "type": page.type, "title": page.title,
            "parent": page.parent_id, "status": page.status}
def present(page: Page) -> Event:   # + "archived": page.archived, "links": [{"to", "role"} ...]
def status(page_id, from_, to)      -> {"page", "kind": "status", "from", "to"}
def renamed(page_id, old, new)      -> {"page", "kind": "renamed", "from": old, "title": new}
def moved(page_id, from_parent, to_parent) -> {"page", "kind": "moved", "from_parent", "to_parent"}
def linked / unlinked(page_id, to, role)   -> {"page", "kind", "to", "role"}
def archived / unarchived(page_id)  -> {"page", "kind"}
def deleted(page)                   -> {"page", "kind": "deleted", "type", "title", "status"}
# private helpers for diff_page: _edited(page_id, section, field), _el_added(..., el, status),
# _el_status(..., el, from_, to), _el_edited(..., el), _el_removed(..., el) - keys in contract order

def stamp(events: list[Event], first_seq: int, ts: int) -> list[Event]:
    return [{"seq": first_seq + i, "ts": ts, "page": e["page"], "kind": e["kind"],
             **{k: v for k, v in e.items() if k not in ("seq", "ts", "page", "kind")}}
            for i, e in enumerate(events)]

def encode(event: Event) -> str:
    return json.dumps(event, ensure_ascii=False, separators=(",", ":")) + "\n"

def diff_page(before: Page, after: Page, page_type: PageType | None) -> list[Event]:
    events = []
    if before.title != after.title: events.append(renamed(after.id, before.title, after.title))
    before_links = [(l["to"], l["role"]) for l in before.links]; after_links = [...]
    linked for pairs in after_links not in before_links (after order); unlinked for pairs only in before (before order)
    if page_type is not None:
        before_sections = initial_sections(page_type, before.sections)
        list_events = []
        for section in page_type.sections:
            for spec in section.fields:
                old = before_sections.get(section.key, {}).get(spec.key)
                new = after.sections.get(section.key, {}).get(spec.key)
                if spec.kind == LIST: list_events += _diff_list(after.id, section.key, spec, old, new)
                elif old != new: events.append(_edited(after.id, section.key, spec.key))
        events += list_events
    if before.status != after.status: events.append(status(after.id, before.status, after.status))
    return events

# _diff_list: elements keyed by their str "id" (others skipped; a non-list value is []);
# has_fsm = spec.element_fsm is not None
# walk after: id not in before -> el_added(status=el.get("status") if has_fsm else None)
#             has_fsm and statuses differ -> el_status; elif dicts differ -> el_edited
# walk before: id not in after -> el_removed

_KIND_KEYS: dict[str, tuple[tuple[str, tuple[type, ...]], ...]] = {
    "created": (("type", STR), ("title", STR), ("parent", STR_OR_NONE), ("status", STR)),
    "present": (... + ("archived", (bool,)), ("links", (list,))),
    "status": (("from", STR), ("to", STR)), "renamed": (("from", STR), ("title", STR)),
    "moved": (("from_parent", STR_OR_NONE), ("to_parent", STR_OR_NONE)),
    "linked"/"unlinked": (("to", STR), ("role", STR)), "archived"/"unarchived": (),
    "deleted": (("type", STR), ("title", STR), ("status", STR)),
    "edited": (("section", STR), ("field", STR)),
    "el_added": (section, field, ("el", STR), ("status", STR_OR_NONE)),
    "el_status": (section, field, el, ("from", STR), ("to", STR)), "el_edited"/"el_removed": (section, field, el)}

def _is_int(v) -> bool: return isinstance(v, int) and not isinstance(v, bool)
def _is_event_line(obj) -> bool: dict, _is_int(seq) and seq >= 1, _is_int(ts), str page, kind in _KIND_KEYS,
    every (key, types) of the kind present with isinstance(value, types)

def check_backfill(text):  # None unless text.endswith("\n"); lines = text[:-1].split("\n");
    # each json.loads (ValueError -> None) and _is_event_line; seq == index + 1; ts >= previous ts

def serve_lines(text):
    pieces = text.split("\n")[:-1]          # the final piece never ends in a newline
    previous = 0
    for piece: parse (skip on ValueError), skip unless dict with _is_int(seq)
        if seq > previous + 1: append {"seq": previous + 1, "ts": obj.get("ts"), "page": None, "kind": "gap", "missing": seq - previous - 1}
        append obj; previous = seq

def timeline_types() -> dict[str, dict[str, Any]]:
    out = {}
    for tag, page_type in sorted(registered_pagetypes().items()):
        fsm = page_type.fsm
        finish = list(fsm.terminal_states) if fsm.terminal_states else (
            [fsm.states[-1]] if fsm.states and fsm.states[-1] != fsm.initial else [])
        out[tag] = {"initial": fsm.initial, "finish": finish,
                    "elements": {f"{s}.{f}": spec.name for s, f, spec in element_fsm_sites(page_type)},
                    "gates": [list(p) for p in sorted({(src, dst) for _e, src, dst, agency in fsm.transitions
                                                         if agency == "human"})]}
    return out

def timeline_payload(workspace_id, name, events):
    return {"workspace": {"id": workspace_id, "name": name},
            "t0": events[0]["ts"] if events else None, "t1": events[-1]["ts"] if events else None,
            "types": timeline_types(), "events": events}

_EPOCH = datetime(1970, 1, 1, tzinfo=timezone.utc)

def _utc_now() -> datetime:
    return datetime.now(timezone.utc)

def _now() -> str:
    return _utc_now().isoformat()

def _commit_instant(updated_at: str) -> datetime:
    now = _utc_now()
    try: loaded = datetime.fromisoformat(updated_at)
    except ValueError: return now
    if loaded.tzinfo is None: loaded = loaded.replace(tzinfo=timezone.utc)
    return max(now, loaded)

def _epoch_ms(instant: datetime) -> int:
    return (instant - _EPOCH) // timedelta(milliseconds=1)

def _touch_and_save(self, workspace, events, backfill=()):
    instant = _commit_instant(workspace.updated_at)
    workspace.updated_at = instant.isoformat(); ts = _epoch_ms(instant)
    installed = list(backfill)
    if installed and installed[-1]["ts"] > ts: logger.warning(...); installed = []
    workspace.event_seq += len(installed)
    lines = installed + (lifecycle_log.stamp(events, workspace.event_seq + 1, ts) if events is not None else [])
    workspace.event_seq += len(events) if events is not None else 1
    self._write_file(self._path_for(workspace.id), workspace)      # the commit
    if lines:
        try: self._append_to_log(workspace.id, lines)
        except Exception: logger.warning("[lifecycle-log] %s: append failed; served as a gap", workspace.id, exc_info=True)

def _append_to_log(self, workspace_id, lines):
    data = "".join(lifecycle_log.encode(line) for line in lines).encode("utf-8")
    path = self._events_path_for(workspace_id); path.parent.mkdir(parents=True, exist_ok=True)
    with self._rw_lock_for(workspace_id).write(), open(path, "ab+") as handle:
        end = handle.seek(0, os.SEEK_END)
        if end:
            _ = handle.seek(end - 1)
            if handle.read(1) != b"\n": data = b"\n" + data
        _ = handle.write(data)

def _load_for_write(self, workspace_id: str) -> Workspace:
    workspace = self.load_workspace(workspace_id)
    if workspace.event_seq != 0:
        return workspace
    path = self._events_path_for(workspace_id)
    try:
        with self._rw_lock_for(workspace_id).read():
            has_lines = path.exists() and path.stat().st_size > 0
            last_seq = _last_logged_seq(path) if has_lines else None
    except OSError:
        logger.warning(...); return workspace
    if has_lines:
        if last_seq is None: logger.warning("... no complete line parses; seq stays 0")
        workspace.event_seq = last_seq or 0
        return workspace
    backfill = self._read_backfill(workspace_id)
    baseline = self._guarded_events(lambda: lifecycle_log.baseline(workspace))
    if backfill or baseline is None or baseline:
        self._touch_and_save(workspace, baseline, backfill=backfill)
    return workspace

def _read_backfill(self, workspace_id) -> list[Event]:   # [] when no backfill_dir or no file
    read bytes, decode utf-8 errors="replace", replace "\r\n" with "\n"; OSError -> warn, []
    checked = lifecycle_log.check_backfill(text); None -> warn, []

def _last_logged_seq(path: Path) -> int | None:  # module helper: read backwards in 64 KiB blocks;
    # complete lines only (the piece after the last b"\n" is ignored); the last one that parses as a
    # JSON object with an int seq (bool rejected) wins; None when none does

pruned_order: list[str] = []
for root_id in sweep.prune:
