(function (root) {
  'use strict';
  const DAY = 86400000, HOUR = 3600000;
  const WARN = ['blocked', 'drifted', 'superseded', 'abandoned', 'failed'];
  const REVIEW = ['judging', 'checking', 'shipping', 'verified'];
  function statusClass(status, typeInfo) {
    if (WARN.includes(status)) return 'warn';
    if (typeInfo && typeInfo.finish.includes(status)) return 'done';
    if (/review/i.test(status) || REVIEW.includes(status)) return 'review';
    if (typeInfo && status === typeInfo.initial) return 'idle';
    return 'active';
  }
  function playheadStep(T, dtSeconds, speed, nextEventTs) {
    const boost = nextEventTs !== null && nextEventTs - T > 6 * HOUR ? 6 : 1;
    return T + dtSeconds * speed * DAY * boost;
  }
  const PastaTimeline = { statusClass, playheadStep /* fold, isShown, ... added by later steps */ };
  root.PastaTimeline = PastaTimeline;
  if (typeof module !== 'undefined' && module.exports) module.exports = PastaTimeline;
})(typeof globalThis !== 'undefined' ? globalThis : this);

