LOG_SUFFIX = ".events.jsonl"
EVENT_KINDS = ("created", "status", "archived", "unarchived")
type Event = dict[str, str]
_REQUIRED = ("at", "event", "pageId")

@dataclass(frozen=True)
class PageMark:
    status: str
    archived: bool

def page_marks(workspace: Workspace) -> dict[str, PageMark]:
    return {page_id: PageMark(page.status, page.archived) for page_id, page in workspace.pages.items()}

def _event(kind: str, page: Page, at: str) -> Event:
    return {"at": at, "event": kind, "pageId": page.id, "type": page.type,
            "title": page.title, "status": page.status}

def lifecycle_events(before: Mapping[str, PageMark], workspace: Workspace, at: str) -> list[Event]:
    events: list[Event] = []
    for page in workspace.pages.values():
        mark = before.get(page.id)
        if mark is None:
            events.append(_event("created", page, at))
            continue
        if page.status != mark.status:
            events.append(_event("status", page, at) | {"from": mark.status})
        if page.archived != mark.archived:
            events.append(_event("archived" if page.archived else "unarchived", page, at))
    return events

def to_jsonl(events: Iterable[Event]) -> str:
    return "".join(json.dumps(event, ensure_ascii=False) + "\n" for event in events)

def parse_jsonl(text: str) -> list[Event]:
    events: list[Event] = []
    for line in text.splitlines():
        if not line.strip():
            continue
        try:
            value = json.loads(line)
        except json.JSONDecodeError:
            continue
        if isinstance(value, dict) and all(isinstance(value.get(key), str) for key in _REQUIRED):
            events.append(value)
    return events

LINE_TYPES = ("feature-brief", "bug-report", "simple-change")
DELIVERED = {"feature-brief": "shipped", "bug-report": "closed", "simple-change": "closed"}
DROPPED = {"feature-brief": "abandoned"}
BASE_RATE = 21_600.0
ACTIVE_WINDOW = 3 * 3600.0
IDLE_PLAYBACK = 1.0
LANE_GAP = 0.4
MIN_LINE = 0.15

@dataclass(frozen=True)
class Segment:
    t0: float
    t1: float
    p0: float
    p1: float

def playback_segments(times: Sequence[float], start: float, end: float) -> list[Segment]:
    if not times or end <= start:
        return []
    windows: list[list[float]] = []
    for t in sorted(times):
        low, high = max(start, t - ACTIVE_WINDOW), min(end, t + ACTIVE_WINDOW)
        if windows and low <= windows[-1][1]:
            windows[-1][1] = max(windows[-1][1], high)
        else:
            windows.append([low, high])
    segments: list[Segment] = []
    cursor, p = start, 0.0
    def add(t1: float, playback: float) -> None:
        nonlocal cursor, p
        if t1 > cursor:
            segments.append(Segment(cursor, t1, p, p + playback))
            cursor, p = t1, p + playback
    for low, high in windows:
        add(low, min((low - cursor) / BASE_RATE, IDLE_PLAYBACK))     # idle gap before the window
        add(high, (high - cursor) / BASE_RATE)                        # the active window itself
    add(end, min((end - cursor) / BASE_RATE, IDLE_PLAYBACK))          # idle tail up to `end`
    return segments

def to_playback(t: float, segments: Sequence[Segment]) -> float:
    if not segments:
        return 0.0
    if t <= segments[0].t0:
        return segments[0].p0
    if t >= segments[-1].t1:
        return segments[-1].p1
    index = bisect_right([s.t0 for s in segments], t) - 1
    segment = segments[index]
    return segment.p0 + (t - segment.t0) / (segment.t1 - segment.t0) * (segment.p1 - segment.p0)

