function rateText(days) {
  if (Math.abs(days - 0.25) < 0.0025) return "";
  return days < 1 ? `${days.toFixed(2)} day per second »` : `${days < 10 ? days.toFixed(1) : Math.round(days)} days per second »`;
}
// per line, inside <a><g class=tl-line --c=...><title/>:
//   drawShapes(el('g', {class: 'tl-ghost'}, group))                 -> unclipped grey copy
//   stops = drawShapes(el('g', {'clip-path': 'url(#tl-clip)'}, group)) -> coloured copy
//   labels = el('g', {}, group) with one <text class=tl-label x=cx+3 y=cy-7
//            transform='rotate(-40 cx+3 cy-7)'> per stop (status, or 'archived'/'unarchived')
// drawShapes(parent): track; one circle per stop (the last of a delivered line is
//   <circle class='tl-stop tl-delivered' r=6> + <path class=tl-check d='M x-2.8 y+0.2 L x-0.8 y+2.2 L x+2.8 y-1.8'>);
//   the dropped bar; returns the stop circles
// frame(): speaking = number > 0 && stop.p <= p && p - stop.p < SPEAK; toggle only on change

.tl-feed li { display: grid; grid-template-columns: 10rem 0.6rem 6.5rem minmax(0, 1fr); gap: 0.6rem;
    align-items: baseline; padding: 0.3rem 0; }
.tl-feed li + li { border-top: 1px solid var(--border); }
#tl-stage { display: block; width: 100%; cursor: grab; user-select: none; touch-action: pan-y; }
#tl-stage.dragging { cursor: grabbing; }

const DRAG_THRESHOLD = 4;   // pixels a press must move before it counts as a drag
let press = null;           // {pointerId, x, p, dragging} while a pointer is down on the stage
stage.addEventListener("pointerdown", (event) => {
  if (event.button !== 0) return;
  press = { pointerId: event.pointerId, x: event.clientX, p, dragging: false };
  stage.setPointerCapture(event.pointerId);
});
stage.addEventListener("pointermove", (event) => {
  if (!press || event.pointerId !== press.pointerId) return;
  const dx = event.clientX - press.x;
  if (!press.dragging && Math.abs(dx) < DRAG_THRESHOLD) return;
  press.dragging = true; stage.classList.add("dragging");
  p = Math.min(data.duration, Math.max(0, press.p - dx / PX)); lastNow = null; frame(); updateButton();
});
function release(event) { /* end the press; if it dragged, mark the next click to be swallowed */ }
stage.addEventListener("pointerup", release); stage.addEventListener("pointercancel", release);
stage.addEventListener("click", (event) => { if (swallowClick) { swallowClick = false; event.preventDefault(); event.stopPropagation(); } }, true);
// tick(): while press is set, keep lastNow = now and do not advance p

// pointermove, where the press first becomes a drag:
press.dragging = true;
setPlaying(false);
stage.setPointerCapture(event.pointerId);

// scrubber:
slider.addEventListener("input", () => {
  setPlaying(false);
  p = parseFloat(slider.value);
  frame();
  updateButton();
});

// tick(): back to `if (lastNow !== null) p = ...` - no `&& !press`

