LOG_SUFFIX = ".events.jsonl"
EVENT_KINDS = ("created", "status", "archived", "unarchived")
type Event = dict[str, str]

@dataclass(frozen=True)
class PageMark:
    status: str
    archived: bool

def page_marks(workspace: Workspace) -> dict[str, PageMark]:
    """status and archived of every page, taken right after a transaction loads the workspace."""

def lifecycle_events(before: Mapping[str, PageMark], workspace: Workspace, at: str) -> list[Event]:
    """The events that turn `before` into `workspace`, in workspace.pages order: 'created' for a
    page absent from before (status = its status now); 'status' with 'from' when the status moved;
    'archived' / 'unarchived' when the flag moved. A page's status event precedes its archive event.
    Pages absent from the workspace (deleted) produce nothing. Nothing changed -> []."""

def to_jsonl(events: Iterable[Event]) -> str:
    """json.dumps(event, ensure_ascii=False) + '\n' per event."""

def parse_jsonl(text: str) -> list[Event]:
    """Every well-formed line in file order. A blank line, a line that is not JSON, not an object,
    or lacks a str 'at' / 'event' / 'pageId' is skipped - a torn last line from an append in
    progress must not break a read."""

def events_path(self, workspace_id: str) -> Path:
    # root / 'ws_<token>.events.jsonl' - the same ':' -> '_' mapping as _path_for

def read_events(self, workspace_id: str) -> list[Event]:
    # [] when the file does not exist; otherwise parse_jsonl of its text. No lock: lines are only
    # ever appended, and a torn last line is dropped by parse_jsonl.

def _touch_and_save(self, workspace: Workspace, before: Mapping[str, PageMark] | None = None) -> None:
    at = _now()
    workspace.updated_at = at
    self._write_file(self._path_for(workspace.id), workspace)
    if before is not None:
        self._append_events(workspace.id, lifecycle_events(before, workspace, at))

def _append_events(self, workspace_id: str, events: list[Event]) -> None:
    # nothing to do for []; else one open(path, 'a', encoding='utf-8').write(to_jsonl(events)).
    # An OSError is logged as a warning on logging.getLogger('uvicorn.error') and swallowed: the
    # workspace file is already saved and is the source of truth, so the write still succeeds.
